def mirror(x):
    if x == 1:
        return ["1"]
    return [str(x)] + mirror(x - 1) + [str(x)]

n = int(input())
print(" ".join(mirror(n)))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

n = int(input())
print(factorial(n))

def rev_str(s):
    if len(s) <= 1:
        return s
    return rev_str(s[1:]) + s[0]

text = input()
print(rev_str(text))

def count_char(s, ch, i=0):
    if i == len(s):
        return 0
    match = 1 if s[i] == ch else 0
    return match + count_char(s, ch, i + 1)

s = input()
ch = input()
print(count_char(s, ch))

def count_digits(n):
    if n < 10:
        return 1
    return 1 + count_digits(n // 10)

n = int(input())
print(count_digits(n))

def to_bin(n):
    if n < 2:
        return str(n)
    return to_bin(n // 2) + str(n % 2)

n = int(input())
print(to_bin(n))

def is_strict(arr, idx=0):
    if idx >= len(arr) - 1:
        return True
    if arr[idx] >= arr[idx + 1]:
        return False
    return is_strict(arr, idx + 1)

arr = [int(x) for x in input().split()]
print("YES" if is_strict(arr) else "NO")

def rec_bs(arr, target, lo, hi, probes=0):
    if lo > hi:
        return -1, probes
    mid = (lo + hi) // 2
    probes += 1
    if arr[mid] == target:
        return mid, probes
    if arr[mid] < target:
        return rec_bs(arr, target, mid + 1, hi, probes)
    return rec_bs(arr, target, lo, mid - 1, probes)

arr = [int(x) for x in input().split()]
target = int(input())
idx, count = rec_bs(arr, target, 0, len(arr) - 1)
print(f"{idx} {count}")

def rec_merge(a, i, b, j):
    if i == len(a):
        return b[j:]
    if j == len(b):
        return a[i:]
    if a[i] <= b[j]:
        return [a[i]] + rec_merge(a, i + 1, b, j)
    return [b[j]] + rec_merge(a, i, b, j + 1)

a = [int(x) for x in input().split()]
b = [int(x) for x in input().split()]
merged = rec_merge(a, 0, b, 0)
print(" ".join(str(x) for x in merged))

def generate_parens(n):
    res = []

    def backtrack(s, open_cnt, close_cnt):
        if len(s) == 2 * n:
            res.append(s)
            return
        if open_cnt < n:
            backtrack(s + "(", open_cnt + 1, close_cnt)
        if close_cnt < open_cnt:
            backtrack(s + ")", open_cnt, close_cnt + 1)

    backtrack("", 0, 0)
    return res

n = int(input())
print(" ".join(generate_parens(n)))

def combination_sum(candidates, target):
    candidates.sort()
    out = []
    path = []

    def dfs(start, rem):
        if rem == 0:
            out.append(" ".join(str(x) for x in path))
            return
        for i in range(start, len(candidates)):
            val = candidates[i]
            if val > rem:
                break
            path.append(val)
            dfs(i, rem - val)
            path.pop()

    dfs(0, target)
    return out

candidates = [int(x) for x in input().split()]
target = int(input())
ans = combination_sum(candidates, target)
if not ans:
    print("NONE")
else:
    for line in ans:
        print(line)
